Lemma bdyn_el (Mx : mem) s fbx (len : nat) q w0 w1 : PQATSW2.bdyn_at RSEGS Mx s fbx len q w0 w1 ->
  L5.u8_at RSEGS Mx s fbx /\ 0 <= fbx < 256 /\ Z.testbit fbx 0 = true /\ L5.u64_at RSEGS Mx (s + 8) (Z.of_nat len) /\ L5.u64_at RSEGS Mx (s + 16) 8
  /\ L5.u64_at RSEGS Mx (s + 24) q /\ q mod 16 = 0 /\ L5.u64_at RSEGS Mx q w0 /\ L5.u64_at RSEGS Mx (q + 8) w1 /\ 0 <= w0 < 2 ^ 64 /\ 0 <= w1 < 2 ^ 64
  /\ L5.defined Mx q 64 /\ PMSPA.accA Mx q 64.
Proof.
