                         (cr' : credit) (D' : list (list Z)) (fbq fbr' r1' : Z),
    regs_preserved R R' ->
    PQATSW2.bdyn_at RSEGS M' o fbq 0%nat pb v0 v1 -> Z.land fbq 2 = Z.land fb 2 ->
    PQATSS.binl_at RSEGS M' rr fbr' 1%nat v0 r1' -> Z.land fbr' 2 = Z.land fb 2 ->
    L5CA.ahpres L ar LBX FF sp SCR W M M' ->
    PMSP.credit_keep cr cr' (TD D) (TD D') ->
    model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' -> incl D D' ->
    ri_inv (HIk D') LBX FF LK' cr' Aw' M' (vml_of model') ->
    srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx' R' r M' model') K.

