Definition keptS (lo n : Z) (Wx : Z -> Prop) (Ma Mb : mem) : Prop :=
  (forall a, spc <= a < sp -> ~ (spc + lo <= a < spc + lo + n) -> Mb (Z_to_bv 64 a) = Ma (Z_to_bv 64 a))
  /\ (forall a, F / 8 + 2147450880 <= a < F / 8 + 2147450880 + 64 -> Mb (Z_to_bv 64 a) = Ma (Z_to_bv 64 a))
  /\ (forall a, (F + 32 <= a < F + 504) \/ (o <= a < o + 32) \/ (rr <= a < rr + 32) -> ~ Wx a -> Mb (Z_to_bv 64 a) = Ma (Z_to_bv 64 a)).
Lemma keptS_binl lo n (Wx : Z -> Prop) (Ma Mb : mem) y fby (len : nat) w0 w1 : keptS lo n Wx Ma Mb ->
  ((F + 32 <= y /\ y + 32 <= F + 504) \/ y = o \/ y = rr) -> (forall a, y <= a < y + 32 -> ~ Wx a) -> 0 <= y -> y + 32 <= 2 ^ 64 ->
  PQATSS.binl_at RSEGS Ma y fby len w0 w1 -> PQATSS.binl_at RSEGS Mb y fby len w0 w1.
Proof.
