(* [comment removed for export] *)
Lemma MSCALL D1 (INC1 : incl D D1) BX1 Aw1 cr1 M3 model3 LK3 (fx3 : FPState) R3 (ra : Z) :
  GM [D1] BX1 M3 model3 LK3 Aw1 cr1 ->
  getr R3 (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> REG0 R3 -> getr R3 (reg 10) = Z_to_bv 64 (F + 168) -> getr R3 (reg 11) = Z_to_bv 64 0 -> getr R3 (reg 12) = Z_to_bv 64 24 ->
  shz M3 20 ->
  (forall R4 (M4 : mem) model4,
      GM [D1] BX1 M4 model4 LK3 Aw1 cr1 -> regs_preserved R3 R4 -> PM.zeros_at M4 (F + 168) 24 -> kept (fun a => F + 168 <= a < F + 192) M3 M4 ->
      (forall q, In (q, 64) (BX1 ++ LBX) -> PMFA.agA M3 M4 q 64) ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx3 R4 ra M4 model4) K) ->
