Lemma AS0CALL D1 (INC1 : incl D D1) BX1 Aw1 cr1 (k : Z) M3 model3 LK3 (fx3 : FPState) R3 (ra fbx : Z) (lend : nat) (e0 e1 fbs s0 s1 : Z) :
  GM [D1] BX1 M3 model3 LK3 Aw1 cr1 -> 32 <= k -> k + 32 <= 504 -> k mod 8 = 0 ->
  getr R3 (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> REG0 R3 -> getr R3 (reg 10) = Z_to_bv 64 o -> getr R3 (reg 11) = Z_to_bv 64 (F + k) ->
