(* [comment removed for export] *)
Lemma AS1CALL D1 (INC1 : incl D D1) BX1 Aw1 cr1 (x k : Z) M3 model3 LK3 (fx3 : FPState) R3 (ra fbx : Z) (lend : nat) (e0 e1 fbs : Z) (pn s0 s1 : Z) :
  GM [D1] BX1 M3 model3 LK3 Aw1 cr1 -> (x = o \/ x = rr) -> 32 <= k -> k + 32 <= 504 -> k mod 8 = 0 ->
  getr R3 (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> REG0 R3 -> getr R3 (reg 10) = Z_to_bv 64 x -> getr R3 (reg 11) = Z_to_bv 64 (F + k) ->
  PQATSS.binl_at RSEGS M3 x fbx lend e0 e1 -> (lend <= 1)%nat -> PQATSW2.bdyn_at RSEGS M3 (F + k) fbs 1%nat pn s0 s1 -> In (pn, 64) (BX1 ++ LBX) -> shz M3 (k / 8) ->
  (forall (fx4 : FPState) R4 (M4 : mem) model4 LK4,
      GM [D1] BX1 M4 model4 LK4 Aw1 cr1 -> regs_preserved R3 R4 -> getr R4 (reg 10) = Z_to_bv 64 x ->
      PQATSS.binl_at RSEGS M4 x (PQATSC.asg_fb fbx fbs 1%nat) 1%nat (PQATSC.asg_w0 e0 s0 1%nat) (PQATSC.asg_w1 e1 lend 1%nat) ->
      PQATSW2.bdyn_at RSEGS M4 (F + k) fbs 1%nat pn s0 s1 ->
      kept (inx x) M3 M4 -> (forall q, In (q, 64) (BX1 ++ LBX) -> PMFA.agA M3 M4 q 64) ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx4 R4 ra M4 model4) K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx3 R3 ASGPC M3 model3) K.
Proof.
