Section AtD1.
Variables (gk1 : list Z) (pn fn x1 : Z) (Aw1 : list (Z * Z)) (cr1 : credit).
Let D1 : list (list Z) := gk1 :: D.
Local Notation BX1 := ([(pn, 64)] : list (Z * Z)).
Hypothesis KIN1 : In gk1 (PQATSG.GKEYS LR PQATSG.OPNEW_RA_A).
Hypothesis CK1 : PMSP.credit_keep cr cr1 (PQATSG.gcostD L gk1 D 64) PMSP.cr0.
Hypothesis Hfn : 0 <= fn <= 255.
Hypothesis Tfn : Z.testbit fn 0 = true.
Let INC1 : incl D D1 := incl_tl gk1 (incl_refl D).
Local Notation NUM Mx := (PQATSW2.bdyn_at RSEGS Mx (F + 96) (Z.land fn 253) 1%nat pn v0 x1).

(* [comment removed for export] *)
Lemma FIN1 M6 model6 LK6 (fx6 : FPState) R6 (fbq fbr' r1' fd : Z) :
  GM [D1] BX1 M6 model6 LK6 Aw1 cr1 ->
  PQATSW2.bdyn_at RSEGS M6 o fbq 0%nat pb v0 v1 -> Z.land fbq 2 = Z.land fb 2 ->
  PQATSS.binl_at RSEGS M6 rr fbr' 1%nat v0 r1' -> Z.land fbr' 2 = Z.land fb 2 ->
  NUM M6 ->
  L5.u8_at RSEGS M6 (F + 32) (Z.land fd 253) -> 0 <= fd <= 255 -> Z.testbit fd 0 = false ->
  REG0 R6 -> getr R6 (reg 18) = Z_to_bv 64 (F / 8 + 2147450880) ->
  getr R6 (reg 20) = Z_to_bv 64 (F + 32) -> getr R6 (reg 21) = Z_to_bv 64 (F + 96) -> getr R6 (reg 24) = Z_to_bv 64 F -> getr R6 (reg 27) = Z_to_bv 64 F ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx6 R6 EXITC M6 model6) K.
Proof.
